/**
 * GET /api/agent-mcp/session-recovery-brief?owner=<sid>[&workspace=<ws>]
 *
 * compaction-continuity-hardening-2026-07-07 P-004: the read the
 * SessionStart[source=compact] recovery hook (session-recover-hook.mjs,
 * generated by interactive-claude-config.ts) fetches right after a compaction —
 * the caller's carry brief rendered as text (armed loop + carry-note, held
 * work-item checkpoints, standing facts, armed awaits, fleet pointer; P-003's
 * renderCarryBriefText). The hook prepends its own static orient-mandate +
 * volatile-claims checklist, so this endpoint carries only the LIVE state.
 *
 * Fail-soft by contract: any build failure returns `{ ok: true, text: '' }` —
 * the hook then injects its static anchor alone. A hook must never surface an
 * error into a session start. `auth: 'loopback'` — the hook runs on this box.
 */
import { defineTool } from '@papercusp/agent-mcp';

const recoveryBrief = defineTool({
  method: 'GET',
  path: '/agent-mcp/session-recovery-brief',
  auth: 'loopback',
  async handler(req) {
    const q = new URL(req.url).searchParams;
    const owner = (q.get('owner') ?? '').trim();
    if (!owner) return Response.json({ ok: false, error: 'owner required' }, { status: 400 });
    const workspace = (q.get('workspace') ?? '').trim() || undefined;
    try {
      const { buildCarryBrief, renderCarryBriefText } = await import('../../../carry-brief');
      const brief = await buildCarryBrief(owner, { workspaceId: workspace });
      const text = renderCarryBriefText(brief);

      // P-003b (memory-delivery-unification-2026-07-12): this endpoint fires
      // exactly once per compaction — it IS the session's epoch boundary.
      // Bump the epoch + run the FULL memory re-prime (resolver rung 0: held
      // work-item titles), appended to the brief. TIME-BOXED: the recovery
      // hook aborts its fetch at ~4.5s, and a slow re-prime must cost only
      // ITSELF, never the carry brief. Best-effort by contract.
      let memoryBlock: string | null = null;
      try {
        const { buildCompactReprimeBlock } = await import('../../../memory/compact-reprime');
        memoryBlock = await Promise.race<string | null>([
          buildCompactReprimeBlock({
            ownerId: owner,
            workspaceId: workspace,
            heldItems: brief.heldItems.map((i) => ({ id: i.id, title: i.title, harness: i.harness })),
            fleetSlug: brief.fleet?.slug ?? null,
            // P-026 (WI-5001) leg (a): threaded through ONLY so the retired-recall
            // branch can derive deterministic query handles from them — never
            // folded into the resolver's speculative query profile.
            awaits: brief.awaits,
            facts: brief.facts,
          }),
          new Promise<null>((resolve) => {
            const t = setTimeout(() => resolve(null), REPRIME_DEADLINE_MS);
            (t as { unref?: () => void }).unref?.();
          }),
        ]);
      } catch {
        memoryBlock = null;
      }

      return Response.json({
        ok: true,
        text: memoryBlock ? `${text}\n\n${memoryBlock}` : text,
      });
    } catch {
      return Response.json({ ok: true, text: '' });
    }
  },
});

/** Re-prime slice of the hook's fetch window (hook aborts ~4.5s). */
const REPRIME_DEADLINE_MS = (() => {
  const raw = Number(process.env.PAPERCUSP_COMPACT_REPRIME_DEADLINE_MS);
  return Number.isFinite(raw) && raw > 0 ? raw : 2_000;
})();

export default [recoveryBrief];
